mapper.select:
SELECT ol.id, ol.user_id, u.username, u.avatar, ol.operation_name, ol.resource_type, ol.resource_id, ol.space_id, s.name AS space_name, d.name AS document_name, ol.resource_name, ol.created_at FROM operation_log ol JOIN user u ON ol.user_id = u.id JOIN space s ON ol.space_id = s.id AND s.deleted = 0 LEFT JOIN document d ON ol.resource_type = 'DOCUMENT' AND ol.resource_id = d.id AND d.deleted = 0 WHERE ol.success = 1 AND NOT (ol.resource_type = 'DOCUMENT' AND ol.resource_id IS NULL) AND ol.space_id IN ( SELECT sm.space_id FROM space_member sm WHERE sm.user_id = #{userId} )
AND ol.space_id = #{spaceId}
ORDER BY ol.id DESC LIMIT #{limit}
